+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+import java.util.regex.Pattern;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final Pattern EMAIL_ADDRESS = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> messages = new Grid<>(ContactMessage.class, false);
+
+    public ContactView() {
+        setPadding(true);
+        setSpacing(true);
+        setMaxWidth("48rem");
+
+        RouterLink about = new RouterLink("About", AboutView.class);
+
+        FormLayout form = new FormLayout();
+        form.setAutoResponsive(true);
+        form.setExpandColumns(true);
+        form.setExpandFields(true);
+        form.setMaxWidth("36rem");
+        form.addFormRow(name, email);
+        form.addFormRow(phone);
+        form.addFormRow(message);
+        form.addFormRow(send);
+
+        message.setWidthFull();
+
+        messages.addColumn(ContactMessage::name).setHeader("Name");
+        messages.addColumn(ContactMessage::message).setHeader("Message");
+        messages.setWidthFull();
+        refreshMessages();
+
+        send.addClickListener(event -> sendMessage());
+        send.addClickShortcut(Key.ENTER);
+        name.addValueChangeListener(event -> enableSending());
+        email.addValueChangeListener(event -> enableSending());
+        phone.addValueChangeListener(event -> enableSending());
+        message.addValueChangeListener(event -> enableSending());
+
+        add(new H1("Contact"), about, form, messages);
+    }
+
+    private void enableSending() {
+        send.setEnabled(true);
+    }
+
+    private void sendMessage() {
+        clearValidationErrors();
+        if (!isValidForm()) {
+            return;
+        }
+
+        ContactMessageStore.add(new ContactMessage(
+                name.getValue(), email.getValue(), phone.getValue(), message.getValue()));
+        refreshMessages();
+        clearForm();
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private boolean isValidForm() {
+        boolean valid = true;
+
+        if (name.getValue().isBlank()) {
+            showError(name, "Name is required");
+            valid = false;
+        }
+
+        String emailValue = email.getValue();
+        if (!emailValue.isBlank() && !EMAIL_ADDRESS.matcher(emailValue).matches()) {
+            showError(email, "Enter a valid e-mail address");
+            valid = false;
+        } else if (emailValue.isBlank() && phone.getValue().isBlank()) {
+            showError(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        if (message.getValue().isBlank()) {
+            showError(message, "Message is required");
+            valid = false;
+        } else if (message.getValue().length() > 500) {
+            showError(message, "Message must be at most 500 characters");
+            valid = false;
+        }
+
+        return valid;
+    }
+
+    private void clearValidationErrors() {
+        clearError(name);
+        clearError(email);
+        clearError(message);
+    }
+
+    private void clearError(com.vaadin.flow.component.HasValidation field) {
+        field.setInvalid(false);
+        field.setErrorMessage(null);
+    }
+
+    private void showError(com.vaadin.flow.component.HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private void clearForm() {
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+    }
+
+    private void refreshMessages() {
+        messages.setItems(ContactMessageStore.all());
+    }
+
+    private boolean hasTypedInput() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty() || !message.isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasTypedInput()) {
+            return;
+        }
+
+        BeforeLeaveEvent.ContinueNavigationAction navigation = event.postpone();
+        Dialog dialog = new Dialog();
+        Button keepEditing = new Button("Keep editing", click -> dialog.close());
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            navigation.proceed();
+        });
+        dialog.add(new Span("You have an unsent message."), new HorizontalLayout(keepEditing, discard));
+        dialog.open();
+    }
+}
